async function writeBlob(body, size, socket) {
  try {
    if (size !== body.size) {
      throw new Error('length mismatch');
    }
    const buffer = Buffer.from(await body.arrayBuffer());
    socket.write(buffer);
  } catch (err) {
    socket.destroy(err);
  }
}

